<script setup lang="ts">
import { Close, Plus } from './internal/icons';
import { ref, computed, provide, reactive, watchEffect, onBeforeUnmount } from 'vue'; import { floatKey } from './float-context'; import FloatButton from './FloatButton.vue';
import './styles/theme.css'; import './styles/float-button.css';
const props = withDefaults(defineProps<{ shape?: 'circle' | 'square'; type?: 'default' | 'primary'; trigger?: 'click' | 'hover'; open?: boolean; description?: string; tooltip?: string; placement?: 'top' | 'bottom' | 'left' | 'right'; inline?: boolean }>(), { open: undefined, shape: 'circle', type: 'default', placement: 'top' }); const emit = defineEmits<{ 'update:open': [value: boolean] }>(); const inner = ref(false); const root = ref<HTMLElement | null>(null); const opened = computed(() => props.open ?? inner.value); const expanded = computed(() => !props.trigger || opened.value);
provide(floatKey, reactive({ get shape() { return props.shape; }, inline: true }));
function setOpen(value: boolean) { if (props.open === undefined) inner.value = value; emit('update:open', value); }
watchEffect(cleanup => { if (!opened.value || typeof document === 'undefined') return; const pointer = (event: PointerEvent) => { if (!root.value?.contains(event.target as Node)) setOpen(false); }; const key = (event: KeyboardEvent) => { if (event.key === 'Escape') setOpen(false); }; document.addEventListener('pointerdown', pointer); document.addEventListener('keydown', key); cleanup(() => { document.removeEventListener('pointerdown', pointer); document.removeEventListener('keydown', key); }); });
let timer: ReturnType<typeof setTimeout>; onBeforeUnmount(() => clearTimeout(timer));
function enter() { clearTimeout(timer); if (props.trigger === 'hover') setOpen(true); } function leave() { if (props.trigger === 'hover') timer = setTimeout(() => setOpen(false), 100); }
</script>
<template><div ref="root" :class="['at-float-button-group', `at-float-button-group--${shape}`, `at-float-button-group--${placement}`, { 'at-float-button-group--menu': trigger, 'at-float-button-group--open': expanded, 'at-float-button-group--inline': inline }]" @mouseenter="enter" @mouseleave="leave"><div class="at-float-button-group__items" :role="trigger ? 'menu' : undefined" :aria-hidden="!expanded" :inert="!expanded"><slot /></div><FloatButton v-if="trigger" :type="type" :shape="shape" inline :description="opened ? undefined : description" :tooltip="tooltip" :aria-expanded="opened" aria-haspopup="menu" class="at-float-button-group__trigger" @click="setOpen(!opened)"><slot v-if="opened" name="closeIcon"><Close :size="20" /></slot><slot v-else name="icon"><Plus :size="22" /></slot></FloatButton></div></template>
